import{_ as a,H as t,f as o,i as n}from"./chunks/framework.DfbB1OsU.js";const u=JSON.parse('{"title":"Background","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Background | trendEcon"}],["meta",{"property":"og:description","content":"Daily economic indicators from Google searches"}],["meta",{"property":"og:url","content":"https://www.trendecon.org/background"}],["meta",{"name":"twitter:title","content":"Background | trendEcon"}],["meta",{"name":"twitter:description","content":"Daily economic indicators from Google searches"}]]},"headers":[],"relativePath":"background.md","filePath":"background.md"}'),r={name:"background.md"};function i(s,e,d,h,l,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h1><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>Official economic statistics are accurate but slow. GDP is quarterly and gets revised for months, and sentiment surveys arrive with a lag. When the situation moves fast, as in a pandemic, an energy shock or a trade dispute, decision-makers need a read on the economy today rather than next quarter.</p><h2 id="the-idea" tabindex="-1">The idea <a class="header-anchor" href="#the-idea" aria-label="Permalink to &quot;The idea&quot;">​</a></h2><p>People reveal their economic concerns through what they search for. A spike in searches for <em>Kurzarbeit</em> (short-time work), <em>Insolvenz</em> (bankruptcy) or <em>arbeitslos</em> (unemployed) is a real-time signal of economic worry. trendEcon turns Google search volumes into daily, continuously updated economic indicators.</p><h2 id="how-the-index-is-built" tabindex="-1">How the index is built <a class="header-anchor" href="#how-the-index-is-built" aria-label="Permalink to &quot;How the index is built&quot;">​</a></h2><p>Turning raw Google Trends into a consistent long daily series is harder than it looks. Google returns <em>relative</em>, <em>rescaled</em> samples whose granularity and normalisation depend on the query window, so naïve queries are noisy and not comparable over time. Our method, published in <em>Economic Inquiry</em>, addresses this in four steps:</p><ol><li><strong>Sampled, overlapping queries.</strong> Each keyword is queried many times over overlapping daily, weekly and monthly windows to average out Google&#39;s sampling noise.</li><li><strong>Harmonisation into one long daily series.</strong> The frequencies are combined so that the long-run trend (from monthly data) and the short-run dynamics (from daily data) are both preserved.</li><li><strong>Seasonal adjustment</strong> removes day-of-week and calendar effects.</li><li><strong>Aggregation.</strong> Related keywords are combined into a single index via principal components.</li></ol><p>The result is a daily index that is stable, comparable across time, and reproducible. The engine is the open-source <a href="https://trendecon.github.io/trendecon/" target="_blank" rel="noreferrer"><code>trendecon</code> R package</a>, and every day&#39;s data is published in the <a href="https://github.com/trendecon/data" target="_blank" rel="noreferrer">data repository</a>.</p><h2 id="reading-the-indicators" tabindex="-1">Reading the indicators <a class="header-anchor" href="#reading-the-indicators" aria-label="Permalink to &quot;Reading the indicators&quot;">​</a></h2><p>Each series is standardised so that its long-run mean is zero and its standard deviation is one. A value of 2 therefore means search interest is two standard deviations above its long-run average, and a value of -1 means one standard deviation below. The indices capture relative changes over time in interest, concern or demand, not absolute search counts, since Google does not publish the underlying number of searches.</p><h2 id="choosing-the-keywords" tabindex="-1">Choosing the keywords <a class="header-anchor" href="#choosing-the-keywords" aria-label="Permalink to &quot;Choosing the keywords&quot;">​</a></h2><p>Each index combines a small set of carefully chosen keywords rather than a single term. We keep only keywords that are likely to reflect an intention to consume rather than general curiosity, and that move with real economic activity. More is not always better: some candidate terms add no extra signal, and Google censors terms with too few searches (returning zeros), so they cannot be used.</p><p>We query German keywords because German is the main language of about 63% of the Swiss population, and German searches track the wider economy well. French and Italian searches within Switzerland hit Google&#39;s privacy threshold more often and get censored, which is another reason we lean on store and brand names: those do not depend on the language the searcher uses.</p><h2 id="the-paper" tabindex="-1">The paper <a class="header-anchor" href="#the-paper" aria-label="Permalink to &quot;The paper&quot;">​</a></h2><blockquote><p>Eichenauer, V. Z., Indergand, R., Martínez, I. Z., &amp; Sax, C. (2022). <em>Obtaining consistent time series from Google Trends.</em> Economic Inquiry, 60(2), 694–705. <a href="https://doi.org/10.1111/ecin.13049" target="_blank" rel="noreferrer">doi.org/10.1111/ecin.13049</a></p></blockquote><p>The paper introduces the sampling-and-harmonisation procedure above, shows that the resulting series are far more reliable than single Google Trends downloads, and validates the indicators against official Swiss figures such as SECO GDP and consumer-sentiment data.</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><p>The indicators reflect <em>attention</em>, not outcomes. A search for a topic signals interest or concern, which usually but not always moves with economic activity. Relationships can shift over time, so the indices are best read as timely, directional signals that complement official statistics rather than replace them.</p>',19)])])}const p=a(r,[["render",i]]);export{u as __pageData,p as default};
